import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_defections = 0
    for _, o in history:
        if o == 'D':
            opp_defections += 1

    my_last, opp_last = history[-1]

    # Endgame
    if n == 99:
        return 'D'
    if n == 98:
        if opp_defections == 0:
            return 'C'
        else:
            return 'D'

    # Defect against confirmed defector
    if n >= 2:
        if opp_defections >= 3 and opp_defections >= n // 2:
            return 'D'

    # Tit-for-two-tats
    if n >= 2:
        if history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'

    # Occasional probing / retaliation against persistent defection
    if opp_last == 'D' and my_last == 'D':
        if rng.random() < 0.7:
            return 'D'

    return 'C'
